var sys = new Solution.AlarmSystem();
var fired = new List<string>();
sys.Triggered += (s, v) => fired.Add(s + ":" + v);
sys.Arm("door", 5);
sys.Reading("door", 3);
sys.Reading("window", 9);
sys.Reading("door", 7);
Cj.Eq(string.Join("|", fired), "door:7", "only armed sensor over threshold fires");
sys.Disarm("door");
sys.Reading("door", 10);
Cj.Eq(fired.Count, 1, "disarmed sensor is silent");

var lv = Solution.LevelsAbove(new List<int> { 1, 5, 7, 2 }, 4);
Cj.Eq(string.Join(",", lv), "5,7", "strictly above, order kept");
var avg = Solution.MakeAverager();
Cj.Eq(avg(10), 10, "first call is the first value");
Cj.Eq(avg(20), 15, "running average so far");
var avg2 = Solution.MakeAverager();
Cj.Eq(avg2(4), 4, "fresh averager starts empty");
Cj.Eq(avg(30), 20, "independent closures keep their own totals");
